#!/usr/bin/env bash
# Copies the Horizon crates the companion checks mods with from a horizon-nx checkout into
# vendor/horizon/, so a mod is judged by the same code as the Switch build's Get Mods.
#
#   packaging/vendor-horizon.sh <horizon-nx checkout>
#
# Run it at the commit of a Horizon NX release (it records it in vendor/horizon/COMMIT), with a
# Rust toolchain that builds horizon-nx: horizon-mod-vocab's API is generated by horizon-nx's
# build, and kept here as generated/. The crates inherit edition, license, rust-version and lints
# from this workspace (Cargo.toml).
set -euo pipefail

src="${1:?usage: $0 <horizon-nx checkout>}"
here="$(cd "$(dirname "$0")/.." && pwd)"
dest="$here/vendor/horizon"
crates=(
    horizon-mod-package
    horizon-mod-vocab
    horizon-mod-api-macros
    horizon-mod-point-shape
    horizon-mod-surface
    horizon-mod-runtime
    horizon-core
    horizon-shader-api
)

[ -d "$src/crates/horizon-mod-package" ] || { echo "$src is not a horizon-nx checkout" >&2; exit 1; }

# horizon-mod-vocab generates its API at build time from sources all over horizon-nx (the game's
# included): build it there once and keep what it generated.
out="$(cd "$src" && cargo check -q -p horizon-mod-vocab --message-format=json 2>/dev/null \
    | python3 "$here/packaging/vendor_out_dir.py" horizon-mod-vocab)"
[ -n "$out" ] && [ -f "$out/mod_api_generated.rs" ] || { echo "no generated horizon-mod-vocab output" >&2; exit 1; }

rm -rf "$dest"
mkdir -p "$dest"
# horizon-nx's layout (crates/, tools/), so the crates' relative paths hold.
for crate in "${crates[@]}"; do
    # The whole crate (its sources read files beside src/), less tests, benches, examples, fixtures.
    mkdir -p "$dest/crates/$crate"
    (cd "$src/crates/$crate" && tar cf - --exclude=./tests --exclude=./benches \
        --exclude=./examples --exclude=./fixtures --exclude=./target .) | (cd "$dest/crates/$crate" && tar xf -)
done
python3 "$here/packaging/vendor_manifests.py" "$dest/crates" "${crates[@]}"
# What horizon-mod-package includes from tools/ (mixins_tool.rs).
mkdir -p "$dest/tools/mixins"
cp "$src/tools/mixins/narrow-reference-rule.patch" "$dest/tools/mixins/"

vocab="$dest/crates/horizon-mod-vocab"
mkdir -p "$vocab/generated"
cp "$out"/*.rs "$vocab/generated/"
# The generator writes the crate's own path into #[path]s: a placeholder, which the build script
# turns into wherever the crate is built.
python3 - "$vocab/generated" "$(cd "$src" && pwd)/crates/horizon-mod-vocab" <<'PY'
import pathlib, sys
generated, crate = pathlib.Path(sys.argv[1]), sys.argv[2]
for path in generated.glob("*.rs"):
    text = path.read_text()
    text = text.replace(crate + "/../../crates/horizon-mod-vocab", "@HORIZON_MOD_VOCAB@")
    text = text.replace(crate, "@HORIZON_MOD_VOCAB@")
    path.write_text(text)
PY
if grep -rlF "$(cd "$src" && pwd)" "$vocab/generated" >/dev/null; then
    echo "a generated file still names $src" >&2
    exit 1
fi
cp "$here/packaging/vocab_build.rs" "$vocab/build.rs"

# Horizon's licence (the LGPL, with the GPL it builds on) and the MIT terms of its older code.
cp "$src/LICENSE" "$dest/LICENSE"
mkdir -p "$dest/LICENSES"
cp "$src"/LICENSES/* "$dest/LICENSES/"
git -C "$src" rev-parse HEAD > "$dest/COMMIT"
echo "vendored ${#crates[@]} crates from $(cat "$dest/COMMIT")"
